CREATE ONE NEW FILE: agents/scs001-hosting/index.ts. Do NOT modify any existing file.

This module provides a VideoHostingService class that uploads a local video file to Supabase Storage and returns a publicly accessible URL for TikTok's PULL_FROM_URL API.

EXACT REQUIREMENTS:

1. IMPORTS:
   import { readFileSync } from 'fs';
   import { basename } from 'path';
   import { createClient, SupabaseClient } from '@supabase/supabase-js';
   No other imports.

2. INTERFACE:
   export interface HostedVideo {
     local_path: string;
     public_url: string;
     bucket: string;
     storage_path: string;
     uploaded_at: string;
     size_bytes: number;
   }

3. CLASS VideoHostingService:
   export class VideoHostingService {
     private supabase: SupabaseClient;
     private bucket: string;

     constructor(opts?: { supabaseUrl?: string; supabaseKey?: string; bucket?: string }) {
       const url = opts?.supabaseUrl ?? process.env.SUPABASE_URL ?? '';
       const key = opts?.supabaseKey ?? process.env.SUPABASE_SERVICE_KEY ?? '';
       this.bucket = opts?.bucket ?? 'scs001-videos';
       this.supabase = createClient(url, key);
     }

     async upload(localPath: string, runId: string): Promise<HostedVideo> {
       const fileBuffer = readFileSync(localPath);
       const storagePath = runId + '/' + basename(localPath);
       const { error } = await this.supabase.storage
         .from(this.bucket)
         .upload(storagePath, fileBuffer, { contentType: 'video/mp4', upsert: true });
       if (error) throw new Error('[VideoHostingService] Upload failed: ' + error.message);
       const { data } = this.supabase.storage.from(this.bucket).getPublicUrl(storagePath);
       return {
         local_path: localPath,
         public_url: data.publicUrl,
         bucket: this.bucket,
         storage_path: storagePath,
         uploaded_at: new Date().toISOString(),
         size_bytes: fileBuffer.length,
       };
     }

     async ensureBucket(): Promise<void> {
       const { data: buckets } = await this.supabase.storage.listBuckets();
       const exists = (buckets ?? []).some(b => b.name === this.bucket);
       if (!exists) {
         const { error } = await this.supabase.storage.createBucket(this.bucket, { public: true });
         if (error) throw new Error('[VideoHostingService] Bucket creation failed: ' + error.message);
         console.log('[VideoHostingService] Created bucket: ' + this.bucket);
       } else {
         console.log('[VideoHostingService] Bucket ' + this.bucket + ' ready');
       }
     }

     static isConfigured(): boolean {
       return !!(process.env.SUPABASE_URL && process.env.SUPABASE_SERVICE_KEY);
     }
   }

FAIL CONDITIONS:
(1) Any file other than agents/scs001-hosting/index.ts created or modified
(2) Import of any package other than @supabase/supabase-js, fs, path
(3) No error handling on upload failure
(4) Missing isConfigured() static method
(5) readFileSync not used to read the local video file
(6) contentType not set to video/mp4

